-- 408: Original BrillaPrep WASSCE Core Mathematics sprint 1 beta questions, part 6 of 8 (batch wassce-core-math-sprint1-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_408_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_408_guard;
INSERT INTO _migration_408_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_031' AND NOT (q.topic_id IS 'topic_wcoremath_trigonometry' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The hypotenuse of a right-angled triangle is 13 cm and one leg is 5 cm. Find the length of the other leg.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 8 cm","B. 18 cm","C. 12 cm","D. √194 cm"]' AND q.correct_answer IS 'C' AND q.explanation IS 'By the theorem of Pythagoras: other leg² = 13² − 5² = 169 − 25 = 144, so the other leg is √144 = 12 cm. (√194 cm wrongly adds the squares.) Therefore the correct answer is C: 12 cm.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_031' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_408_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_032' AND NOT (q.topic_id IS 'topic_wcoremath_trigonometry' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In a right-angled triangle, sin θ = 5/13. Find the value of cos θ.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 13/5","B. 5/12","C. 13/12","D. 12/13"]' AND q.correct_answer IS 'D' AND q.explanation IS 'sin θ = opposite/hypotenuse = 5/13, so by Pythagoras the adjacent side is √(13² − 5²) = √144 = 12. Hence cos θ = adjacent/hypotenuse = 12/13. (5/12 is tan θ.) Therefore the correct answer is D: 12/13.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_032' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_408_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_033' AND NOT (q.topic_id IS 'topic_wcoremath_statistics' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Find the mean of the numbers 2, 4, 6, 8 and 10.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 6","B. 5","C. 10","D. 30"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Mean = (2 + 4 + 6 + 8 + 10) ÷ 5 = 30 ÷ 5 = 6. (30 is the total, not the mean.) Therefore the correct answer is A: 6.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_033' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_408_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_034' AND NOT (q.topic_id IS 'topic_wcoremath_statistics' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The ages of six children are 3, 5, 3, 7, 3 and 5 years. What is the modal age?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 5 years","B. 3 years","C. 7 years","D. 4 years"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The mode is the most frequent value: 3 occurs three times, 5 occurs twice and 7 occurs once, so the modal age is 3 years. Therefore the correct answer is B: 3 years.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_034' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_408_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_035' AND NOT (q.topic_id IS 'topic_wcoremath_statistics' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Find the median of the numbers 2, 3, 5, 8 and 9.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 5.4","B. 3","C. 5","D. 8"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The numbers are already in ascending order, so the median is the middle (3rd) value, 5. (5.4 is the mean, a different average.) Therefore the correct answer is C: 5.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_035' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_408_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_036' AND NOT (q.topic_id IS 'topic_wcoremath_statistics' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A fair die is thrown once. What is the probability of obtaining an even number?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 1/3","B. 1/6","C. 2/3","D. 1/2"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The even outcomes are 2, 4 and 6 — three of the six equally likely outcomes — so the probability is 3/6 = 1/2. Therefore the correct answer is D: 1/2.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_036' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s1_031', 'topic_wcoremath_trigonometry', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'The hypotenuse of a right-angled triangle is 13 cm and one leg is 5 cm. Find the length of the other leg.', 'multiple_choice', NULL, '["A. 8 cm","B. 18 cm","C. 12 cm","D. √194 cm"]', 'C', 'By the theorem of Pythagoras: other leg² = 13² − 5² = 169 − 25 = 144, so the other leg is √144 = 12 cm. (√194 cm wrongly adds the squares.) Therefore the correct answer is C: 12 cm.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec');
