INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s1_033', 'topic_wcoremath_statistics', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Find the mean of the numbers 2, 4, 6, 8 and 10.', 'multiple_choice', NULL, '["A. 6","B. 5","C. 10","D. 30"]', 'A', 'Mean = (2 + 4 + 6 + 8 + 10) ÷ 5 = 30 ÷ 5 = 6. (30 is the total, not the mean.) Therefore the correct answer is A: 6.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO1', NULL, NULL, 'board_waec');
